CREATE OR REPLACE FUNCTION public.pago_credito_representado(_id uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT COALESCE(sum(ca.monto),0) FROM public.mp_account_movements mp JOIN public.cuenta_ajustes ca ON ca.referencia_externa=mp.mp_payment_id AND ca.cuenta_mp_id=mp.cuenta_mp_id AND upper(ca.moneda)=upper(mp.currency) WHERE mp.id=_id AND ca.tipo='credito'; $$;
REVOKE ALL ON FUNCTION public.pago_credito_representado(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pago_credito_representado(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.pago_consumido_legacy(_tipo text,_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT CASE _tipo WHEN 'mp_movement' THEN (public.pago_credito_representado(_id)>=public.pago_monto_bruto(_tipo,_id) OR EXISTS(SELECT 1 FROM public.mp_account_movements mp JOIN public.suscripciones s ON s.id=mp.suscripcion_id WHERE mp.id=_id AND s.cancelada_at IS NULL AND s.estado IN ('activa','pendiente_verificacion','vencida','finalizada','conciliado') AND public.is_subscription_paid(s.id) AND mp.amount<=public.obligacion_monto('suscripcion',s.id)) OR EXISTS(SELECT 1 FROM public.mp_account_movements mp JOIN public.reservation_payments rp ON rp.id=mp.reservation_payment_id WHERE mp.id=_id AND rp.anulado_at IS NULL AND COALESCE(rp.status,'')<>'rechazado' AND COALESCE(rp.amount,0)>=mp.amount) OR EXISTS(SELECT 1 FROM public.mp_account_movements mp JOIN public.reservation_payments rp ON rp.alumno_id=mp.alumno_id AND (rp.mp_payment_id=mp.mp_payment_id OR rp.payment_reference=mp.mp_payment_id) WHERE mp.id=_id AND rp.anulado_at IS NULL AND rp.status='validado' AND upper(rp.currency)=upper(mp.currency) AND COALESCE(rp.amount,0)>=mp.amount)) ELSE false END; $$;
CREATE OR REPLACE FUNCTION public.pago_monto_legacy(_tipo text,_id uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT CASE WHEN _tipo='mp_movement' THEN LEAST(COALESCE(public.pago_monto_bruto(_tipo,_id),0),GREATEST(public.pago_credito_representado(_id),COALESCE((SELECT LEAST(mp.amount,public.obligacion_monto('suscripcion',s.id)) FROM public.mp_account_movements mp JOIN public.suscripciones s ON s.id=mp.suscripcion_id WHERE mp.id=_id AND s.cancelada_at IS NULL AND s.estado<>'cancelada' AND public.is_subscription_paid(s.id)),0),COALESCE((SELECT sum(rp.amount) FROM public.mp_account_movements mp JOIN public.reservation_payments rp ON (rp.id=mp.reservation_payment_id OR (rp.mp_payment_id=mp.mp_payment_id OR rp.payment_reference=mp.mp_payment_id) AND rp.alumno_id=mp.alumno_id) WHERE mp.id=_id AND rp.anulado_at IS NULL AND rp.status='validado' AND upper(rp.currency)=upper(mp.currency)),0),CASE WHEN EXISTS(SELECT 1 FROM public.mp_account_movements mp WHERE mp.id=_id AND mp.suscripcion_id IS NOT NULL) THEN 0 ELSE CASE WHEN public.pago_consumido_legacy(_tipo,_id) THEN COALESCE(public.pago_monto_bruto(_tipo,_id),0) ELSE 0 END END)) ELSE 0 END; $$;
REVOKE ALL ON FUNCTION public.pago_monto_legacy(text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pago_monto_legacy(text,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.pago_saldo_disponible(_tipo text,_id uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT GREATEST(0,COALESCE(public.pago_monto_bruto(_tipo,_id),0)-public.pago_monto_legacy(_tipo,_id)-public.pago_monto_imputado(_tipo,_id)); $$;
CREATE OR REPLACE VIEW public.vw_pagos_disponibles WITH(security_invoker=true) AS SELECT alumno_id,'mp_movement'::text pago_origen_tipo,id pago_origen_id,mp_payment_id,fecha_movimiento fecha,COALESCE(description,'Mercado Pago') concepto,currency moneda,amount monto_bruto,public.pago_monto_imputado('mp_movement',id) monto_imputado,public.pago_consumido_legacy('mp_movement',id) consumido_legacy,public.pago_saldo_disponible('mp_movement',id) disponible FROM public.mp_account_movements WHERE alumno_id IS NOT NULL AND direccion='ingreso' AND status='approved';
CREATE OR REPLACE FUNCTION public.obligacion_saldo_pendiente(_tipo text,_id uuid) RETURNS numeric LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE t text:=public.obligacion_tipo_normalizado(_tipo); total numeric; paid numeric:=0; BEGIN total:=public.obligacion_monto(t,_id); IF total IS NULL THEN RETURN NULL; END IF; IF t='suscripcion' THEN IF EXISTS(SELECT 1 FROM public.suscripciones WHERE id=_id AND (cancelada_at IS NOT NULL OR estado='cancelada')) THEN RETURN 0; END IF; SELECT COALESCE(sum(amount),0) INTO paid FROM public.mp_account_movements WHERE suscripcion_id=_id AND status='approved' AND direccion='ingreso'; IF paid=0 AND public.is_subscription_paid(_id) THEN RETURN 0; END IF; SELECT paid+COALESCE(sum(ca.monto),0) INTO paid FROM public.cuenta_ajustes ca WHERE ca.tipo='credito' AND ca.aplicado_a_fuente_tabla='suscripciones' AND ca.aplicado_a_fuente_id=_id AND NOT EXISTS(SELECT 1 FROM public.mp_account_movements mp WHERE mp.suscripcion_id=_id AND mp.status='approved' AND mp.mp_payment_id=ca.referencia_externa AND mp.cuenta_mp_id=ca.cuenta_mp_id); END IF; RETURN GREATEST(0,total-GREATEST(paid,0)-public.obligacion_imputado(t,_id)); END $$;
DO $view$ DECLARE v text; needle text:=$old$    pi.monto AS haber,$old$; replacement text:=$new$    CASE WHEN pi.pago_origen_tipo='mp_movement' THEN LEAST(pi.monto,GREATEST(0,(SELECT COALESCE(sum(p2.monto),0) FROM public.pagos_imputaciones p2 WHERE p2.pago_origen_tipo=pi.pago_origen_tipo AND p2.pago_origen_id=pi.pago_origen_id AND p2.anulado_at IS NULL AND (p2.created_at,p2.id)<=(pi.created_at,pi.id))-GREATEST(0,public.pago_monto_legacy(pi.pago_origen_tipo,pi.pago_origen_id)+public.pago_monto_imputado(pi.pago_origen_tipo,pi.pago_origen_id)-public.pago_monto_bruto(pi.pago_origen_tipo,pi.pago_origen_id)))) ELSE pi.monto END AS haber,$new$; BEGIN v:=pg_get_viewdef('public.vw_cuenta_corriente_movimientos'::regclass,true); IF strpos(v,needle)=0 THEN RAISE EXCEPTION 'Unexpected account statement definition'; END IF; v:=replace(v,needle,replacement); v:=replace(v,' AND NOT pago_consumido_legacy(pi.pago_origen_tipo, pi.pago_origen_id)',''); EXECUTE 'CREATE OR REPLACE VIEW public.vw_cuenta_corriente_movimientos WITH(security_invoker=true) AS '||v; END $view$;
CREATE OR REPLACE FUNCTION public.guard_pagos_imputaciones() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bruto numeric; usado numeric; legacy numeric; pend numeric; ob_alumno uuid; ob_moneda text; BEGIN IF NEW.anulado_at IS NOT NULL THEN RETURN NEW; END IF; IF NEW.monto IS NULL OR NEW.monto<=0 THEN RAISE EXCEPTION 'invalid_imputation_amount'; END IF; IF TG_OP='UPDATE' AND (NEW.pago_origen_tipo,NEW.pago_origen_id) IS DISTINCT FROM (OLD.pago_origen_tipo,OLD.pago_origen_id) THEN RAISE EXCEPTION 'imputation_source_is_immutable'; END IF; IF NEW.pago_origen_tipo='mp_movement' THEN PERFORM 1 FROM public.mp_account_movements WHERE id=NEW.pago_origen_id AND direccion='ingreso' AND status='approved' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'approved_income_not_found'; END IF; ELSIF NEW.pago_origen_tipo='cuenta_ajuste' THEN PERFORM 1 FROM public.cuenta_ajustes WHERE id=NEW.pago_origen_id FOR UPDATE; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('imputation:source:'||NEW.pago_origen_tipo||':'||NEW.pago_origen_id,0)); NEW.obligacion_tipo:=public.obligacion_tipo_normalizado(NEW.obligacion_tipo); IF NEW.obligacion_tipo IS NULL THEN RAISE EXCEPTION 'invalid_obligation_type'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('imputation:target:'||NEW.obligacion_tipo||':'||NEW.obligacion_id,0)); IF NEW.obligacion_tipo='suscripcion' THEN PERFORM 1 FROM public.suscripciones WHERE id=NEW.obligacion_id FOR UPDATE; ELSIF NEW.obligacion_tipo='reserva' THEN PERFORM 1 FROM public.event_reservations WHERE id=NEW.obligacion_id FOR UPDATE; ELSIF NEW.obligacion_tipo='otro' THEN PERFORM 1 FROM public.cuenta_ajustes WHERE id=NEW.obligacion_id FOR UPDATE; END IF; bruto:=public.pago_monto_bruto(NEW.pago_origen_tipo,NEW.pago_origen_id); IF bruto IS NULL AND NEW.pago_origen_tipo<>'manual' THEN RAISE EXCEPTION 'payment_not_found'; END IF; SELECT COALESCE(sum(monto),0) INTO usado FROM public.pagos_imputaciones WHERE pago_origen_tipo=NEW.pago_origen_tipo AND pago_origen_id=NEW.pago_origen_id AND anulado_at IS NULL AND id<>NEW.id; legacy:=public.pago_monto_legacy(NEW.pago_origen_tipo,NEW.pago_origen_id); IF bruto IS NOT NULL AND usado+legacy+NEW.monto>bruto+0.01 THEN RAISE EXCEPTION 'payment_already_represented_or_overallocated'; END IF; ob_alumno:=public.obligacion_alumno(NEW.obligacion_tipo,NEW.obligacion_id); ob_moneda:=public.obligacion_moneda(NEW.obligacion_tipo,NEW.obligacion_id); IF ob_alumno IS DISTINCT FROM NEW.alumno_id THEN RAISE EXCEPTION 'obligation_identity_mismatch'; END IF; IF upper(ob_moneda) IS DISTINCT FROM upper(NEW.moneda) THEN RAISE EXCEPTION 'obligation_currency_mismatch'; END IF; IF NEW.pago_origen_tipo='mp_movement' AND EXISTS(SELECT 1 FROM public.mp_account_movements mp WHERE mp.id=NEW.pago_origen_id AND (mp.alumno_id IS DISTINCT FROM NEW.alumno_id OR upper(mp.currency) IS DISTINCT FROM upper(NEW.moneda))) THEN RAISE EXCEPTION 'payment_identity_or_currency_mismatch'; END IF; pend:=public.obligacion_saldo_pendiente(NEW.obligacion_tipo,NEW.obligacion_id); IF TG_OP='UPDATE' AND OLD.anulado_at IS NULL THEN pend:=pend+OLD.monto; END IF; IF pend IS NULL OR NEW.monto>pend+0.01 THEN RAISE EXCEPTION 'obligation_already_paid_or_overallocated'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.imputar_pago(_pago_origen_tipo text,_pago_origen_id uuid,_obligacion_tipo text,_obligacion_id uuid,_alumno_id uuid,_monto numeric,_moneda text DEFAULT 'ARS',_metadata jsonb DEFAULT '{}') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_existing public.pagos_imputaciones; v_id uuid; BEGIN IF NOT (public.has_role(auth.uid(),'admin'::public.app_role) OR public.is_super_admin(auth.uid())) THEN RAISE EXCEPTION 'not_authorized'; END IF; IF _pago_origen_tipo='mp_movement' THEN PERFORM 1 FROM public.mp_account_movements WHERE id=_pago_origen_id FOR UPDATE; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('imputation:source:'||_pago_origen_tipo||':'||_pago_origen_id,0)); _obligacion_tipo:=public.obligacion_tipo_normalizado(_obligacion_tipo); IF _monto IS NULL OR _monto<=0 THEN RAISE EXCEPTION 'El monto a imputar debe ser mayor que cero'; END IF; SELECT * INTO v_existing FROM public.pagos_imputaciones WHERE pago_origen_tipo=_pago_origen_tipo AND pago_origen_id=_pago_origen_id AND obligacion_tipo=_obligacion_tipo AND obligacion_id=_obligacion_id AND anulado_at IS NULL LIMIT 1; IF FOUND THEN IF round(v_existing.monto,2)=round(_monto,2) THEN RETURN v_existing.id; END IF; RAISE EXCEPTION 'Ya existe una imputación activa por otro importe'; END IF; INSERT INTO public.pagos_imputaciones(pago_origen_tipo,pago_origen_id,obligacion_tipo,obligacion_id,alumno_id,monto,moneda,created_by,metadata) VALUES(_pago_origen_tipo,_pago_origen_id,_obligacion_tipo,_obligacion_id,_alumno_id,_monto,COALESCE(_moneda,'ARS'),auth.uid(),COALESCE(_metadata,'{}')) RETURNING id INTO v_id; RETURN v_id; END $$;
REVOKE EXECUTE ON FUNCTION public.imputar_pago(text,uuid,text,uuid,uuid,numeric,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.imputar_pago(text,uuid,text,uuid,uuid,numeric,text,jsonb) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.guard_credit_mp_budget() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mp record; credits numeric; used numeric; BEGIN IF NEW.tipo<>'credito' OR NEW.referencia_externa IS NULL OR NEW.cuenta_mp_id IS NULL THEN RETURN NEW; END IF; SELECT * INTO mp FROM public.mp_account_movements WHERE mp_payment_id=NEW.referencia_externa AND cuenta_mp_id=NEW.cuenta_mp_id AND upper(currency)=upper(NEW.moneda) AND status='approved' AND direccion='ingreso' FOR UPDATE; IF NOT FOUND THEN RETURN NEW; END IF; SELECT COALESCE(sum(monto),0) INTO credits FROM public.cuenta_ajustes WHERE tipo='credito' AND referencia_externa=NEW.referencia_externa AND cuenta_mp_id=NEW.cuenta_mp_id AND upper(moneda)=upper(NEW.moneda) AND id<>NEW.id; used:=public.pago_monto_imputado('mp_movement',mp.id); IF credits+NEW.monto+used>mp.amount+0.01 THEN RAISE EXCEPTION 'mp_credit_budget_exceeded'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_guard_credit_mp_budget BEFORE INSERT OR UPDATE OF monto,tipo,referencia_externa,cuenta_mp_id,moneda ON public.cuenta_ajustes FOR EACH ROW EXECUTE FUNCTION public.guard_credit_mp_budget();
CREATE OR REPLACE FUNCTION public.guard_mp_legacy_vs_imputations() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF (NEW.suscripcion_id,NEW.reservation_payment_id) IS DISTINCT FROM (OLD.suscripcion_id,OLD.reservation_payment_id) AND (NEW.suscripcion_id IS NOT NULL OR NEW.reservation_payment_id IS NOT NULL) AND public.pago_monto_imputado('mp_movement',NEW.id)>0 THEN RAISE EXCEPTION 'movement_has_active_imputations'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_guard_mp_legacy_vs_imputations BEFORE UPDATE OF suscripcion_id,reservation_payment_id ON public.mp_account_movements FOR EACH ROW EXECUTE FUNCTION public.guard_mp_legacy_vs_imputations();
DO $rpc$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.aplicar_saldo_disponible(text,uuid,text,uuid,numeric)'::regprocedure); IF strpos(d,'IF NOT public._programa_admin_ok()')=0 THEN RAISE EXCEPTION 'Unexpected balance application authorization'; END IF; d:=replace(d,'IF NOT public._programa_admin_ok()','IF NOT (public.has_role(auth.uid(),''admin''::public.app_role) OR public.is_super_admin(auth.uid()))'); EXECUTE d; END $rpc$;